// mixedSuite returns the checks as data, drawn from f.
//
// The seam the proofs companion binds to, and the one a runner of your
// own would. It takes the fixture rather than a config because the
// fixture is what a check draws from; a config that derives one is the
// pool work, and until that lands a caller passes what a default run
// passes.
func mixedSuite(fx MixedFixture) suite.Suite[Mixed] {
	return suite.Suite[Mixed]{
		Name:     "Mixed",
		DropHint: mixedDropHint,
		Checks:   mixedSignatureChecks(fx),
	}
}

// mixedSignatureChecks builds every check this run derived.
//
// sig is the one shape they share; the literals below state only what
// differs. Falsifiable is Proven wherever a defect rule reached the
// claim AND the companion beside this file spells that defect — the
// parity gate refuses the stamp without the evidence, so a claim this
// run cannot yet plant is argued rather than asserted.
func mixedSignatureChecks(fx MixedFixture) []suite.Check[Mixed] {
	sig := suite.ProvenCheck[Mixed]
	ix := mixedCheckIndex
	return []suite.Check[Mixed]{
		sig(ix.Add.Smoke(), suite.ClassSmoke,
			"Add survives a call with a derived item",
			func(tb testing.TB, m Mixed) {
				mixedAssertAddSmoke(tb, m, fx)
			}),
		sig(ix.Add.Cancels(), suite.ClassCancel,
			"Add reports a cancelled context as cancelled",
			func(tb testing.TB, m Mixed) {
				mixedAssertAddCancels(tb, m, fx)
			}),
		sig(ix.Add.NilContext(), suite.ClassNilContext,
			"Add returns an error rather than panicking on a nil context",
			func(tb testing.TB, m Mixed) {
				mixedAssertAddToleratesNilContext(tb, m, fx)
			}),
		sig(ix.Add.Deadline(), suite.ClassDeadline,
			"Add reports an expired deadline as exceeded",
			func(tb testing.TB, m Mixed) {
				mixedAssertAddHonoursDeadline(tb, m, fx)
			}),
		sig(ix.Items.Smoke(), suite.ClassSmoke,
			"Items survives a call",
			func(tb testing.TB, m Mixed) {
				mixedAssertItemsSmoke(tb, m)
			}),
		sig(ix.Items.Cancels(), suite.ClassCancel,
			"Items reports a cancelled context as cancelled",
			func(tb testing.TB, m Mixed) {
				mixedAssertItemsCancels(tb, m)
			}),
		sig(ix.Items.NilContext(), suite.ClassNilContext,
			"Items returns an error rather than panicking on a nil context",
			func(tb testing.TB, m Mixed) {
				mixedAssertItemsToleratesNilContext(tb, m)
			}),
		sig(ix.Items.Deadline(), suite.ClassDeadline,
			"Items reports an expired deadline as exceeded",
			func(tb testing.TB, m Mixed) {
				mixedAssertItemsHonoursDeadline(tb, m)
			}),
		sig(ix.Items.ZeroOnError(), suite.ClassZeroValue,
			"Items returns nothing alongside any error",
			func(tb testing.TB, m Mixed) {
				mixedAssertItemsZeroOnError(tb, m)
			}),
	}
}

